def num_decodings(s):
    prev, cur = 1, 1
    for i in range(len(s)):
        nxt = cur if s[i] != "0" else 0
        if i and s[i - 1] != "0" and 10 <= int(s[i - 1:i + 1]) <= 26:
            nxt += prev
        prev, cur = cur, nxt
    return cur
